VALUES (NULL, NULL, 214402, 'Under the Waves', 'Under the Waves', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co545p.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1tgy.jpg', 'Under the Waves is a narrative-driven adventure game about the engulfing power of grief. Set in the depths of the North Sea in a techno-futuristic 1970s, professional diver Stan is struggling to overcome a life-changing loss and embrace a new future. The isolation of the deep sea is a fitting manifestation of his state of mind, and as Stan retreads further into his self-imposed solitude, he starts to experience strange events far beneath the waves. Stuck between life and death, Stan will have to make the most significant choice of his existence.', 'https://www.igdb.com/games/under-the-waves', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 7.1, 0, 9.51, '2026-11-20 22:18:41', '2026-11-20 22:18:41')
