VALUES (NULL, NULL, 46681, 'Garry Kitchen''s Super Battletank: War in the Gulf', 'Garry Kitchen''s Super Battletank: War in the Gulf', 'game', 1992, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3gns.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8h9r.jpg', 'Garry Kitchen''s Super Battletank: War in the Gulf, is a tank simulation game. The Game Gear version is simply known as Super Battletank. Both versions were only released in North America.', 'https://www.igdb.com/games/garry-kitchens-super-battletank-war-in-the-gulf', '["Super Nintendo Entertainment System", "Sega Mega Drive/Genesis", "Sega Game Gear", "Game Boy"]', NULL, 4.1, 0, 8.51, '2026-11-20 22:18:41', '2026-11-20 22:18:41')
