VALUES (NULL, NULL, 9254, 'Subnautica', 'Subnautica', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa938.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6yzp.jpg', 'Descend into the depths of an alien underwater world filled with wonder and peril. Craft equipment, pilot submarines and out-smart wildlife to explore lush coral reefs, volcanoes, cave systems, and more, all while trying to survive.', 'https://www.igdb.com/games/subnautica', '["Xbox Series X|S", "PlayStation 4", "Nintendo Switch 2", "Android", "PC (Microsoft Windows)", "iOS", "SteamVR", "PlayStation 5", "Mac", "Oculus Rift", "Xbox One", "Nintendo Switch"]', NULL, 8.3, 0, 8.70833333333333392e+00, '2026-11-19 20:56:22', '2026-11-20 22:18:41')
