VALUES (NULL, NULL, 132356, 'Armoured Commander II', 'Armoured Commander II', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ces.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/armdk.jpg', 'In Armoured Commander II, you take on the role of a tank commander in World War II. Featuring a roguelike focus on turn-based and procedurally-generated strategic gameplay, you must lead your tank crew through a multi-week campaign where your ultimate goal is simply to survive.', 'https://www.igdb.com/games/armoured-commander-ii', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 6.045, '2026-11-19 20:56:22', '2026-11-20 22:18:41')
